def p(d,t,style=None):return d.add_paragraph(t,style)
def h(d,t):return p(d,t,'Heading 1')
def new(title,intro):
 d=Document();p(d,title,'Title');p(d,intro);return d
def block(d,title,rows):
 if title:h(d,title)
 t=d.add_table(rows=0,cols=1)
 for text in rows:t.add_row().cells[0].text=text
 return t
def grid(d,headers,rows):
 t=d.add_table(rows=1,cols=len(headers))
 for c,x in zip(t.rows[0].cells,headers):c.text=x
 for row in rows:
  for c,x in zip(t.add_row().cells,row):c.text=x
 return t
